// ===========================
// State Management
// ===========================

let appState = {
    currentPage: 'home',
    currentView: 'dashboard', // 'dashboard', 'quiz', 'level-complete'
    darkMode: false,
    sidebarOpen: false,
    userProfile: {
        name: 'Sign Connect User',
        email: 'user123@gmail.com',
        avatar: null
    },
    earnedBadges: [],
    quizState: {
        currentLevelId: null,
        currentQuestionIndex: 0,
        selectedAnswer: null,
        correctAnswers: 0,
        answeredQuestions: [],
        showFeedback: false,
        completedLevels: []
    }
};

// ===========================
// Initialization
// ===========================

document.addEventListener('DOMContentLoaded', () => {
    loadState();
    initializeEventListeners();
    renderCurrentView();
});

function loadState() {
    // Load theme
    const savedTheme = localStorage.getItem('sign-connect-theme');
    if (savedTheme === 'dark') {
        appState.darkMode = true;
        document.body.classList.remove('light-theme');
        document.body.classList.add('dark-theme');
    }

    // Load profile
    const savedProfile = localStorage.getItem('sign-connect-profile');
    if (savedProfile) {
        try {
            appState.userProfile = JSON.parse(savedProfile);
        } catch (e) {
            console.error('Failed to parse profile');
        }
    }

    // Load completed levels
    const savedLevels = localStorage.getItem('sign-connect-completed-levels');
    if (savedLevels) {
        try {
            appState.quizState.completedLevels = JSON.parse(savedLevels);
        } catch (e) {
            console.error('Failed to parse completed levels');
        }
    }

    // Load earned badges
    const savedBadges = localStorage.getItem('sign-connect-badges');
    if (savedBadges) {
        try {
            appState.earnedBadges = JSON.parse(savedBadges);
        } catch (e) {
            console.error('Failed to parse badges');
        }
    }

    updateHeaderProfile();
}

function saveProfile() {
    localStorage.setItem('sign-connect-profile', JSON.stringify(appState.userProfile));
}

function saveCompletedLevels() {
    localStorage.setItem('sign-connect-completed-levels', JSON.stringify(appState.quizState.completedLevels));
}

// ===========================
// Event Listeners
// ===========================

function initializeEventListeners() {
    // Header
    document.getElementById('menuBtn').addEventListener('click', toggleSidebar);
    document.getElementById('themeBtn').addEventListener('click', toggleTheme);
    document.getElementById('userBtn').addEventListener('click', openProfileModal);

    // Sidebar
    document.getElementById('closeBtn').addEventListener('click', closeSidebar);
    document.getElementById('overlay').addEventListener('click', closeSidebar);

    document.querySelectorAll('.nav-item').forEach(item => {
        item.addEventListener('click', () => {
            const page = item.getAttribute('data-page');
            navigateTo(page);
        });
    });

    // Profile Modal
    document.getElementById('profileModalBackdrop').addEventListener('click', (e) => {
        if (e.target.id === 'profileModalBackdrop') {
            closeProfileModal();
        }
    });
    document.getElementById('profileModalClose').addEventListener('click', closeProfileModal);
    document.getElementById('profileCancelBtn').addEventListener('click', closeProfileModal);
    document.getElementById('profileForm').addEventListener('submit', handleProfileSave);
    document.getElementById('profileAvatarUploadBtn').addEventListener('click', () => {
        document.getElementById('profileAvatarInput').click();
    });
    document.getElementById('profileAvatarInput').addEventListener('change', handleAvatarChange);
}
// ===========================
// Theme Toggle
// ===========================

function toggleTheme() {
    appState.darkMode = !appState.darkMode;
    
    if (appState.darkMode) {
        document.body.classList.remove('light-theme');
        document.body.classList.add('dark-theme');
        localStorage.setItem('sign-connect-theme', 'dark');
    } else {
        document.body.classList.remove('dark-theme');
        document.body.classList.add('light-theme');
        localStorage.setItem('sign-connect-theme', 'light');
    }
}

// ===========================
// Sidebar
// ===========================

function toggleSidebar() {
    appState.sidebarOpen = !appState.sidebarOpen;
    updateSidebar();
}

function closeSidebar() {
    appState.sidebarOpen = false;
    updateSidebar();
}

function updateSidebar() {
    const sidebar = document.getElementById('sidebar');
    const overlay = document.getElementById('overlay');
    
    if (appState.sidebarOpen) {
        sidebar.classList.add('active');
        overlay.classList.add('active');
    } else {
        sidebar.classList.remove('active');
        overlay.classList.remove('active');
    }
}

// ===========================
// Navigation
// ===========================

function navigateTo(page) {
    appState.currentPage = page;
    appState.currentView = 'dashboard';
    
    // Update active nav item
    document.querySelectorAll('.nav-item').forEach(item => {
        if (item.getAttribute('data-page') === page) {
            item.classList.add('active');
        } else {
            item.classList.remove('active');
        }
    });

    closeSidebar();
    renderCurrentView();
}

// ===========================
// Profile Modal
// ===========================

function openProfileModal() {
    // Always re-read latest badges from localStorage before opening profile
    const savedBadges = localStorage.getItem('sign-connect-badges');
    if (savedBadges) {
        try { appState.earnedBadges = JSON.parse(savedBadges).map(Number); } catch(e) {}
    }
    const savedLevels = localStorage.getItem('sign-connect-completed-levels');
    if (savedLevels) {
        try { appState.quizState.completedLevels = JSON.parse(savedLevels).map(Number); } catch(e) {}
    }
    updateProfileModalData();
    document.getElementById('profileModalBackdrop').classList.add('active');
}

function closeProfileModal() {
    document.getElementById('profileModalBackdrop').classList.remove('active');
}

function updateProfileModalData() {
    const completedCount = appState.quizState.completedLevels.length;
    const totalLevels = levelsData.length;
    const score = (completedCount / totalLevels) * 100;

    document.getElementById('profileScore').textContent = Math.round(score) + '%';
    document.getElementById('profileAccuracy').textContent = '0%';
    document.getElementById('profileCurrentLevel').textContent = 'Level ' + Math.min(completedCount + 1, totalLevels);
    document.getElementById('profileLevelProgress').style.width = ((completedCount + 1) / totalLevels * 100) + '%';

    document.getElementById('profileName').value = appState.userProfile.name;
    document.getElementById('profileEmail').value = appState.userProfile.email;

    const initials = appState.userProfile.name.split(' ').slice(0, 2).map(p => p.charAt(0).toUpperCase()).join('') || 'SC';
    document.getElementById('profileInitials').textContent = initials;

    // Update badges display — always show all badges (earned highlighted, locked greyed out)
    const earnedBadges = getBadgesEarned();
    const badgesBody = document.getElementById('profileBadgesBody');
    badgesBody.innerHTML = `
        <div class="profile-badges-grid">
            ${badgesData.map(badge => {
                const earned = appState.earnedBadges.includes(Number(badge.id));
                return `
                    <div class="profile-badge-item ${earned ? 'earned' : 'locked'}">
                        <div class="profile-badge-img-wrap">
                            <img src="${badgeImages[badge.level]}" alt="${badge.name}" class="profile-badge-img ${earned ? '' : 'locked-img'}">
                            ${!earned ? '<div class="badge-lock-overlay">🔒</div>' : ''}
                        </div>
                        <span class="profile-badge-label">${badge.name}</span>
                    </div>
                `;
            }).join('')}
        </div>
        <p class="profile-badges-count">${earnedBadges.length} / ${badgesData.length} badges earned</p>
    `;

    const avatarImage = document.getElementById('profileAvatarImage');
    if (appState.userProfile.avatar) {
        avatarImage.style.backgroundImage = `url(${appState.userProfile.avatar})`;
        document.getElementById('profileInitials').style.display = 'none';
    } else {
        avatarImage.style.backgroundImage = '';
        document.getElementById('profileInitials').style.display = 'block';
    }
}

function handleProfileSave(e) {
    e.preventDefault();
    
    const name = document.getElementById('profileName').value.trim();
    const email = document.getElementById('profileEmail').value.trim();

    if (name) appState.userProfile.name = name;
    if (email) appState.userProfile.email = email;

    saveProfile();
    updateHeaderProfile();
    closeProfileModal();
}

function handleAvatarChange(e) {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
        appState.userProfile.avatar = event.target.result;
        saveProfile();
        updateHeaderProfile();
        updateProfileModalData();
    };
    reader.readAsDataURL(file);
}

function updateHeaderProfile() {
    document.getElementById('headerUserName').textContent = appState.userProfile.name;
    
    const avatar = document.getElementById('headerUserAvatar');
    if (appState.userProfile.avatar) {
        avatar.style.backgroundImage = `url(${appState.userProfile.avatar})`;
        avatar.textContent = '';
    } else {
        avatar.style.backgroundImage = '';
        avatar.textContent = appState.userProfile.name.charAt(0).toUpperCase();
    }
}

// ===========================
// Render Views
// ===========================

function renderCurrentView() {
    const container = document.getElementById('mainContainer');
    
    if (appState.currentView === 'dashboard') {
        if (appState.currentPage === 'home') {
            container.innerHTML = renderHomePage();
            attachHomeHandlers();
        } else if (appState.currentPage === 'asl-learning') {
            container.innerHTML = renderASLLearningPage();
            attachASLLearningHandlers();
        } else if (appState.currentPage === 'asl-colors') {
            container.innerHTML = renderASLColorsPage();
            attachASLColorsPageHandlers();
        } else if (appState.currentPage === 'asl-numbers') {
            container.innerHTML = renderASLNumbersPage();
            attachASLNumbersPageHandlers();
        } else if (appState.currentPage === 'asl-fruits') {
            container.innerHTML = renderASLFruitsPage();
            attachASLFruitsPageHandlers();
        } else if (appState.currentPage === 'asl-everyday') {
            container.innerHTML = renderASLEverydayPage();
            attachASLEverydayPageHandlers();
        } else if (appState.currentPage === 'asl-drinks') {
            container.innerHTML = renderASLDrinksPage();
            attachASLDrinksPageHandlers();
        } else if (appState.currentPage === 'asl-vegetables') {
            container.innerHTML = renderASLVegetablesPage();
            attachASLVegetablesPageHandlers();
        } else if (appState.currentPage === 'asl-alphabet') {
            container.innerHTML = renderASLAlphabetPage();
            attachASLAlphabetPageHandlers();
        } else if (appState.currentPage === 'asl-grammar') {
            container.innerHTML = renderASLGrammarPage();
            attachASLGrammarPageHandlers();
        } else if (appState.currentPage === 'about') {
            container.innerHTML = renderAboutPage();
            attachAboutHandlers();
        } else if (appState.currentPage === 'visual-interpreter') {
            container.innerHTML = renderVisualInterpreterPage();
            attachVisualInterpreterHandlers();
        } else if (appState.currentPage === 'donation') {
            container.innerHTML = renderDonationPage();
            attachDonationHandlers();
        } else if (appState.currentPage === 'daily-tasks') {
            container.innerHTML = renderDailyTasksPage();
            attachDailyTasksHandlers();
        } else {
            container.innerHTML = renderPlaceholderPage(appState.currentPage);
        }
    } else if (appState.currentView === 'quiz') {
        container.innerHTML = renderQuizPage();
        attachQuizHandlers();
    } else if (appState.currentView === 'level-complete') {
        container.innerHTML = renderLevelCompletePage();
        attachLevelCompleteHandlers();
    }

    window.scrollTo(0, 0);
}

// ===========================
// Home Page
// ===========================

function renderHomePage() {
    const completedCount = appState.quizState.completedLevels.length;
    const totalLevels = levelsData.length;
    const overallScore = (completedCount / totalLevels) * 100;

    let levelsHTML = '';
    levelsData.forEach((level) => {
        const previousLevelId = level.id - 1;
        const isUnlocked = level.id === 1 || appState.quizState.completedLevels.includes(previousLevelId);
        const isCompleted = appState.quizState.completedLevels.includes(level.id);

        const lockIcon = isCompleted 
            ? '<polyline points="20 6 9 17 4 12"></polyline>'
            : isUnlocked 
            ? '<rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect><path d="M7 11V7a5 5 0 0 1 9.9-1"></path>'
            : '<rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect><path d="M7 11V7a5 5 0 0 1 10 0v4"></path>';

        const description = isCompleted 
            ? `Completed! ${level.questions.length} questions mastered`
            : isUnlocked
            ? level.description
            : `Complete Level ${previousLevelId} to unlock`;

        const badge = isCompleted ? 'Completed' : isUnlocked ? 'Start' : 'Locked';

        levelsHTML += `
            <div class="level-item ${isUnlocked ? 'unlocked' : ''}" data-level-id="${level.id}">
                <div class="level-icon">
                    <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        ${lockIcon}
                    </svg>
                </div>
                <div class="level-content">
                    <h4 class="level-title">${level.title}</h4>
                    <p class="level-description">${description}</p>
                </div>
                <span class="level-badge">${badge}</span>
            </div>
        `;
    });

    return `
        <div class="page-section">
            <div class="page-header">
                <div class="page-header-content">
                    <h1 class="page-header-title">
                        <div class="page-header-icon">
                            <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                <path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"></path>
                                <polyline points="9 22 9 12 15 12 15 22"></polyline>
                            </svg>
                        </div>
                        Welcome back, ${appState.userProfile.name}!
                    </h1>
                    <p class="page-header-description">Continue your ASL learning journey today</p>
                </div>
            </div>

            <div class="stats-grid">
                <div class="stat-card primary">
                    <div class="stat-card-header">
                        <h3 class="stat-card-title">Overall Score</h3>
                        <div class="stat-card-icon">
                            <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                <path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"></path>
                                <path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"></path>
                                <path d="M4 22h16"></path>
                                <path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"></path>
                                <path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"></path>
                                <path d="M18 2H6v7a6 6 0 0 0 12 0V2Z"></path>
                            </svg>
                        </div>
                    </div>
                    <div class="stat-card-value">${Math.round(overallScore)}%</div>
                    <div class="progress-bar">
                        <div class="progress-fill primary" style="width: ${overallScore}%"></div>
                    </div>
                </div>

                <div class="stat-card accent">
                    <div class="stat-card-header">
                        <h3 class="stat-card-title">Levels Completed</h3>
                        <div class="stat-card-icon">
                            <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                <circle cx="12" cy="12" r="10"></circle>
                                <circle cx="12" cy="12" r="6"></circle>
                                <circle cx="12" cy="12" r="2"></circle>
                            </svg>
                        </div>
                    </div>
                    <div class="stat-card-value">${completedCount}/${totalLevels}</div>
                    <div class="progress-bar">
                        <div class="progress-fill accent" style="width: ${(completedCount / totalLevels) * 100}%"></div>
                    </div>
                </div>

                <div class="stat-card secondary">
                    <div class="stat-card-header">
                        <h3 class="stat-card-title">Current Level</h3>
                        <div class="stat-card-icon">
                            <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                <polyline points="23 6 13.5 15.5 8.5 10.5 1 18"></polyline>
                                <polyline points="17 6 23 6 23 12"></polyline>
                            </svg>
                        </div>
                    </div>
                    <div class="stat-card-value">Level ${Math.min(completedCount + 1, totalLevels)}</div>
                    <div class="progress-bar">
                        <div class="progress-fill secondary" style="width: ${((completedCount + 1) / totalLevels) * 100}%"></div>
                    </div>
                </div>
            </div>

            <div class="card">
                <div class="card-header">
                    <div class="card-accent"></div>
                    <h2 class="card-title">Learning Path</h2>
                </div>
                <div class="level-list">
                    ${levelsHTML}
                </div>
            </div>

            <div class="card">
                <div class="card-header">
                    <div class="stat-card-icon" style="background: linear-gradient(to bottom right, var(--primary), var(--accent));">
                        <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="color: white;">
                            <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path>
                            <polyline points="22 4 12 14.01 9 11.01"></polyline>
                        </svg>
                    </div>
                    <h2 class="card-title">Challenge To-Do List</h2>
                </div>
                <div class="level-list">
                    ${['Complete 5 lessons', 'Practice alphabet 3 times', 'Score 80% in a quiz', 'Learn 20 new signs'].map(task => `
                        <div class="level-item" style="cursor: pointer;">
                            <div style="width: 24px; height: 24px; border: 2px solid rgba(74, 155, 168, 0.4); border-radius: 8px; flex-shrink: 0;"></div>
                            <div class="level-content">
                                <span class="level-title" style="font-size: 16px;">${task}</span>
                            </div>
                            <div style="width: 8px; height: 8px; border-radius: 50%; background: rgba(74, 155, 168, 0.2);"></div>
                        </div>
                    `).join('')}
                </div>
            </div>
        </div>
    `;
}

function attachHomeHandlers() {
    document.querySelectorAll('.level-item.unlocked').forEach(item => {
        item.addEventListener('click', () => {
            const levelId = parseInt(item.getAttribute('data-level-id'));
            startLevel(levelId);
        });
    });
}

