        carrot: '<path d="m2.27 21.7 9.82-9.82M8.64 13.36l-2.82-2.82M10.6 11.4l-2.82-2.82M12.56 9.44l-2.82-2.82M3 3l18 18M12 21a6 6 0 0 0-6-6M6 9a6 6 0 0 0 6 6M3 3a6 6 0 0 0 6 6"></path>',
