function renderASLAlphabetPage() {
    return `
        <div class="page-section">
            <div class="quiz-container">
                <button class="back-btn" id="backToASLLearningFromAlphabet">
                    <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        <line x1="19" y1="12" x2="5" y2="12"></line>
                        <polyline points="12 19 5 12 12 5"></polyline>
                    </svg>
                    <span>Back to ASL Learning</span>
                </button>
            </div>
            ${renderASLAlphabetCards()}
        </div>
    `;
}

function renderASLAlphabetCards() {
    const signs = [
        {
            letter: 'A',
            accent: '#c62828',
            image: 'data:image/png;base64,',
            instructions: 'Make a fist with your thumb resting against the side of your index finger.'
        },
        {
            letter: 'B',
            accent: '#1565c0',
            image: 'data:image/png;base64,',
            instructions: 'Flat palm, fingers together, thumb tucked across the palm.'
        },
        {
            letter: 'C',
            accent: '#2e7d32',
            image: 'data:image/png;base64,',
            instructions: 'Curve your hand into a "C" shape, like you\'re holding a cup.'
        },
        {
            letter: 'D',
            accent: '#6a1b9a',
            image: 'data:image/png;base64,',
            instructions: 'Point your index finger up; touch your thumb to the other three fingers to form a circle.'
        },
        {
            letter: 'E',
            accent: '#e65100',
            image: 'data:image/png;base64,',
            instructions: 'Curl all fingers down so the tips rest on top of your thumb, which is tucked under.'
        },
        {
            letter: 'F',
            accent: '#00695c',
            image: 'data:image/png;base64,',
            instructions: 'Touch your index and thumb together in a circle; keep the other three fingers up (looks like "OK").'
        },
        {
            letter: 'G',
            accent: '#ad1457',
            image: 'data:image/png;base64,',
            instructions: 'Point your index and thumb parallel to each other, like you\'re pinching something small. The palm faces you while your fingers point sideways.'
        },
        {
            letter: 'H',
            accent: '#4e342e',
            image: 'data:image/png;base64,',
            instructions: 'Extend your index and middle fingers together, pointing sideways. The palm faces you while your fingers point sideways.'
        },
        {
            letter: 'I',
            accent: '#1a237e',
            image: 'data:image/png;base64,',
            instructions: 'Make a fist but extend your pinky finger straight up.'
        },
        {
            letter: 'J',
            accent: '#33691e',
            image: 'data:image/png;base64,',
            instructions: 'Keep the "I" shape and trace a "J" in the air with your pinky.'
        },
        {
            letter: 'K',
            accent: '#880e4f',
            image: 'data:image/png;base64,',
            instructions: 'Index finger up, middle finger out at an angle, thumb touches the middle finger\'s joint. Your middle finger points slightly forward toward the person you are talking to.'
        },
        {
            letter: 'L',
            accent: '#bf360c',
            image: 'data:image/png;base64,',
            instructions: 'Form an "L" shape with your thumb and index finger.'
        },
        {
            letter: 'M',
            accent: '#01579b',
            image: 'data:image/png;base64,',
            instructions: 'Fold your thumb under your index, middle, and ring fingers.'
        },
        {
            letter: 'N',
            accent: '#004d40',
            image: 'data:image/png;base64,',
            instructions: 'Fold your thumb under your index and middle fingers only.'
        },
        {
            letter: 'O',
            accent: '#4a148c',
            image: 'data:image/png;base64,',
            instructions: 'Curve all fingers to touch your thumb, forming an "O" circle.'
        },
        {
            letter: 'P',
            accent: '#1b5e20',
            image: 'data:image/png;base64,',
            instructions: 'Index finger up, middle finger out at an angle, thumb touches the middle finger\'s joint. Your middle finger points slightly forward toward the person you are talking to.'
        },
        {
            letter: 'Q',
            accent: '#37474f',
            image: 'data:image/png;base64,',
            instructions: 'Make a "G" shape but point it downward. Your wrist tilts down so the palm faces the floor. The side of your index finger and the back of your hand faces you.'
        },
        {
            letter: 'R',
            accent: '#3e2723',
            image: 'data:image/png;base64,',
            instructions: 'Cross your index and middle fingers (like "fingers crossed").'
        },
        {
            letter: 'S',
            accent: '#f57f17',
            image: 'data:image/png;base64,',
            instructions: 'Make a fist and place your thumb across the front of all fingers.'
        },
        {
            letter: 'T',
            accent: '#0d47a1',
            image: 'data:image/png;base64,',
            instructions: 'Make a fist and tuck your thumb under your index finger only.'
        },
        {
            letter: 'U',
            accent: '#b71c1c',
            image: 'data:image/png;base64,',
            instructions: 'Extend your index and middle fingers straight up and tight together.'
        },
        {
            letter: 'V',
            accent: '#1b5e20',
            image: 'data:image/png;base64,',
            instructions: 'Extend your index and middle fingers in a "V" shape.'
        },
        {
            letter: 'W',
            accent: '#4a148c',
            image: 'data:image/png;base64,',
            instructions: 'Extend index, middle, and ring fingers (looks like the number 3 but palm out).'
        },
        {
            letter: 'X',
            accent: '#e65100',
            image: 'data:image/png;base64,',
            instructions: 'Make a fist and hook your index finger like a pirate\'s hook.'
        },
        {
            letter: 'Y',
            accent: '#006064',
            image: 'data:image/png;base64,',
            instructions: 'Extend your thumb and pinky; keep the middle fingers folded.'
        },
        {
            letter: 'Z',
            accent: '#212121',
            image: 'data:image/png;base64,',
            instructions: 'Use your index finger to trace a "Z" in the air.'
        },
    ];

    const cardsHTML = signs.map(s => `
        <div class="asl-color-card">
            <div class="asl-sign-banner">
                ${s.image
                    ? `<img class="asl-sign-img" src="${s.image}" alt="${s.letter} ASL sign" loading="lazy" />`
                    : `<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:#f0f4f8;font-size:4rem;font-weight:800;color:${s.accent};">${s.letter}</div>`
                }
            </div>
            <div class="asl-color-card-body">
                <div class="asl-color-name-row">
                    <div class="asl-fruit-badge" style="background: ${s.accent};">${s.letter}</div>
                    <div class="asl-color-name-stack">
                        <div class="asl-color-name">Letter ${s.letter}</div>
                        <div class="asl-color-subtitle">ASL Sign</div>
                    </div>
                </div>
                <div class="asl-color-divider"></div>
                <div class="asl-color-instructions">${s.instructions}</div>
                <div class="asl-color-hint">Tap to read more ↓</div>
            </div>
        </div>
    `).join('');

    return `
        <div class="asl-category-detail">
            <div class="asl-category-detail-header">
                <div class="asl-category-detail-title">Letters & Alphabet 🤟</div>
                <div class="asl-category-detail-desc">Learn all 26 letters of the ASL alphabet. Tap any card to see full instructions.</div>
            </div>
            <div class="asl-cards-grid" aria-label="ASL alphabet signs">
                ${cardsHTML}
            </div>
        </div>
    `;
}

function attachASLAlphabetCardHandlers() {
    document.querySelectorAll('.asl-color-card').forEach(card => {
        card.addEventListener('click', () => card.classList.toggle('active'));
    });
}

function attachASLAlphabetPageHandlers() {
    const back = document.getElementById('backToASLLearningFromAlphabet');
    if (back) back.addEventListener('click', () => navigateTo('asl-learning'));
    attachASLAlphabetCardHandlers();
}

