function renderASLGrammarPage() {
    return `
        <div class="page-section">
            <div class="quiz-container">
                <button class="back-btn" id="backToASLLearning">
                    <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        <line x1="19" y1="12" x2="5" y2="12"></line>
                        <polyline points="12 19 5 12 12 5"></polyline>
                    </svg>
                    <span>Back to ASL Learning</span>
                </button>
            </div>
            ${renderASLGrammarCards()}
        </div>
    `;
}

function renderASLGrammarCards() {
    const signs = [
        {
            word: 'Family',
            image: 'data:image/png;base64,',
            emoji: '👨‍👩‍👧‍👦',
            accent: '#1565c0',
            instructions: 'Form "F" handshapes with both hands. Hold both "F" hands in front of your chest, with your thumbs and index fingers touching. Move both hands away from each other in an outward circle. Bring your hands back together.'
        },
        {
            word: 'Friend',
            image: 'data:image/png;base64,',
            emoji: '🤝',
            accent: '#2e7d32',
            instructions: 'Extend the index fingers on both hands (the "1" handshape) and curl them slightly like hooks. Hook your dominant index finger over the top of your non-dominant index finger. Pull them apart slightly, flip your hands over, and hook them again with the non-dominant finger now on top. This "interlocking" movement happens twice.'
        },
        {
            word: 'Mother',
            image: 'data:image/png;base64,',
            emoji: '👩',
            accent: '#ad1457',
            instructions: 'Open your dominant hand into a "5" handshape. Place the tip of your thumb against the center of your chin. Tap your thumb against your chin twice.'
        },
        {
            word: 'Father',
            image: 'data:image/png;base64,',
            emoji: '👨',
            accent: '#1565c0',
            instructions: 'Open your dominant hand into a "5" handshape. Place the tip of your thumb against the center of your forehead. Tap your thumb against your forehead twice.'
        },
        {
            word: 'House',
            image: 'data:image/png;base64,',
            emoji: '🏠',
            accent: '#e65100',
            instructions: 'Form both hands into flat palms with your fingers together. Touch the tips of your fingers together so your hands form a triangle or upside-down "V" shape. Move your hands outward and downward along the diagonal, tracing the slanting roofline. Once your hands reach the "corners" of the roof, move them straight down to represent the vertical walls. Stop with your hands parallel, palms facing inward.'
        },
        {
            word: 'Eat',
            image: 'data:image/png;base64,',
            emoji: '🍽️',
            accent: '#6a1b9a',
            instructions: 'Form a "flattened O" with your dominant hand. Hold your hand just in front of your mouth. Tap your fingertips against your lips or just in front of them once or twice.'
        },
        {
            word: 'School',
            image: 'data:image/png;base64,',
            emoji: '🏫',
            accent: '#00695c',
            instructions: 'Hold your non-dominant hand flat in front of you, palm facing upward. Hold your dominant hand flat, palm facing downward. Bring your dominant hand down to clap against the palm of your non-dominant hand. Repeat the clap twice.'
        },
        {
            word: 'Happy',
            image: 'data:image/png;base64,',
            emoji: '😊',
            accent: '#f57f17',
            instructions: 'Open both hands into flat palms. Place your palms against your chest, one slightly above the other. Move both hands in an upward, circular brushing motion. As your hands move up, they should pull slightly away from your chest and then "loop" back down to repeat the stroke.'
        },
        {
            word: 'Love',
            image: 'data:image/png;base64,',
            emoji: '❤️',
            accent: '#b71c1c',
            instructions: 'Cross both fists over your chest in an "X" shape (palms facing in), pressing them against your heart as if giving a hug.'
        },
        {
            word: 'Age',
            image: 'data:image/png;base64,',
            emoji: '🧓',
            accent: '#4e342e',
            instructions: 'Form a relaxed "C" handshape or a loose fist (the "S" handshape) with your dominant hand. Place your hand just below your chin, as if you are grabbing an invisible beard. Pull your hand downward away from your chin. As you pull down, gradually close your hand into a fist.'
        },
        {
            word: 'Work',
            image: 'data:image/png;base64,',
            emoji: '💼',
            accent: '#37474f',
            instructions: 'Form both hands into relaxed fists. Hold your non-dominant hand still in front of you, with your palm facing down. Place your dominant hand on top. Tap the base of your dominant palm (the "heel" of your hand) against the top of your non-dominant wrist or the back of your hand. Repeat the tapping motion twice.'
        },
        {
            word: 'Play',
            image: 'data:image/png;base64,',
            emoji: '🎮',
            accent: '#1a237e',
            instructions: 'Form a "Y" handshape with both hands. Hold your hands out in front of you at about chest or shoulder height, with your palms facing toward your body. Twist your wrists back and forth rapidly. The hands should shake or rotate inward and outward simultaneously.'
        },
        {
            word: 'Student',
            image: 'data:image/png;base64,',
            emoji: '🎒',
            accent: '#4a148c',
            instructions: 'Hold your non-dominant hand flat in front of you, palm facing up. Place the fingertips of your dominant hand on the palm of your flat hand, then "grab" an invisible thought and pull it up to your forehead. Immediately drop both hands to your sides with palms facing each other. Move both flat hands straight down along the sides of your torso.'
        },
        {
            word: 'Teacher',
            image: 'data:image/png;base64,',
            emoji: '👩‍🏫',
            accent: '#004d40',
            instructions: 'Form both hands into flattened "O" shapes. Hold your hands near your temples or forehead, with your palms facing each other. Move both hands forward and outward away from your head twice in a small, double motion. Then open both hands into flat palms facing each other and move both hands straight down the sides of your torso.'
        },
        {
            word: 'Understand',
            image: 'data:image/png;base64,',
            emoji: '💡',
            accent: '#e65100',
            instructions: 'Form a fist with your dominant hand. Place your fist near the side of your forehead (your temple), with your palm facing inward toward your head. Quickly flick your index finger up so it points toward the ceiling, while keeping the rest of your fingers in a fist. It\'s a sharp, single flick — like a "1" popping up.'
        },
        {
            word: 'Finish',
            image: 'data:image/png;base64,',
            emoji: '✅',
            accent: '#1b5e20',
            instructions: 'Open both hands into a "5" handshape. Hold both hands in front of you at chest height, with your palms facing your body. Quickly flick or rotate your wrists so that your palms end up facing outward (away from you). It should be a sharp, singular movement.'
        },
        {
            word: 'More',
            image: 'data:image/png;base64,',
            emoji: '➕',
            accent: '#0d47a1',
            instructions: 'Form "flattened O" shapes with both hands. Hold your hands in front of your chest with your fingertips pointing toward each other. Bring your hands together so your fingertips touch or tap against each other. Tap your fingertips together twice.'
        }
    ];

    const cardsHTML = signs.map(s => `
        <div class="asl-color-card">
            <div class="asl-sign-banner">
                <img class="asl-sign-img" src="${s.image}" alt="${s.word} ASL sign" loading="lazy" />
            </div>
            <div class="asl-color-card-body">
                <div class="asl-color-name-row">
                    <div class="asl-fruit-badge" style="background: ${s.accent};">${s.word.charAt(0)}</div>
                    <div class="asl-color-name-stack">
                        <div class="asl-color-name">${s.word}</div>
                        <div class="asl-color-subtitle">ASL Sign</div>
                    </div>
                </div>
                <div class="asl-color-divider"></div>
                <div class="asl-color-instructions">${s.instructions}</div>
                <div class="asl-color-hint">Tap to read more ↓</div>
            </div>
        </div>
    `).join('');

    return `
        <div class="asl-category-detail">
            <div class="asl-category-detail-header">
                <div class="asl-category-detail-title">Everyday Things 💬</div>
                <div class="asl-category-detail-desc">Learn essential ASL signs for everyday grammar and communication. Tap any card to see full instructions.</div>
            </div>
            <div class="asl-cards-grid" aria-label="ASL grammar signs">
                ${cardsHTML}
            </div>
        </div>
    `;
}

function attachASLGrammarCardHandlers() {
    document.querySelectorAll('.asl-color-card').forEach(card => {
        card.addEventListener('click', () => card.classList.toggle('active'));
    });
}

function attachASLGrammarPageHandlers() {
    const back = document.getElementById('backToASLLearning');
    if (back) back.addEventListener('click', () => navigateTo('asl-learning'));
    attachASLGrammarCardHandlers();
}

