function renderASLFruitsCards() {
    const fruits = [
        {
            name: 'Fruit',
            signImg: 'data:image/png;base64,',
            accent: '#2e7d32',
            instructions: 'Form an "F" handshape with your dominant hand. Place the tips of your thumb and index finger against the side of your cheek, near the corner of your mouth. Twist your wrist back and forth twice while keeping your fingers in the "F" shape.'
        },
        {
            name: 'Apple',
            signImg: 'data:image/png;base64,',
            accent: '#c62828',
            instructions: 'Form an "X" handshape with your dominant hand. Place the bent knuckle of your index finger against your cheek, near the side of your mouth. Twist your hand back and forth while keeping the knuckle in contact with your cheek. Repeat twice.'
        },
        {
            name: 'Banana',
            signImg: 'data:image/png;base64,',
            accent: '#f57f17',
            instructions: 'Hold your non-dominant index finger pointing up like a banana. With your dominant hand, reach to the top of that finger and "peel" downward. Repeat this peeling movement 2–3 times, moving around the finger to mimic peeling different sides of the banana.'
        },
        {
            name: 'Orange',
            signImg: 'data:image/png;base64,',
            accent: '#e65100',
            instructions: 'Form a loose fist. Place your hand directly in front of your chin or mouth. Squeeze your hand into a tight fist and then relax it slightly. Repeat this "squeezing" motion twice.'
        },
        {
            name: 'Pear',
            signImg: 'data:image/png;base64,',
            accent: '#558b2f',
            instructions: 'Form a flattened "O" handshape with your non-dominant hand, fingertips pointing upward. Place your dominant hand over your non-dominant hand. Slide your dominant hand upward and off the fingertips. Repeat this sliding motion twice.'
        },
        {
            name: 'Peach',
            signImg: 'data:image/png;base64,',
            accent: '#bf360c',
            instructions: 'Place the tips of your fingers against the side of your cheek. Glide your hand down your cheek toward your chin while gently drawing your fingertips together. Repeat this motion twice.'
        },
        {
            name: 'Blueberry',
            signImg: 'data:image/png;base64,',
            accent: '#4527a0',
            instructions: 'BLUE: Form a "B" handshape and twist your wrist a couple of times. BERRY: Hold out the index finger of your non-dominant hand sideways. With your dominant hand, grasp the tip of that finger with all fingers and thumb. Twist your dominant hand back and forth on the tip of the finger.'
        },
        {
            name: 'Cherry',
            signImg: 'data:image/png;base64,',
            accent: '#880e4f',
            instructions: 'Extend your non-dominant index finger pointing slightly upward and forward. Place the tips of your dominant fingers around the tip of that finger. Twist your dominant hand back and forth once or twice.'
        },
        {
            name: 'Coconut',
            signImg: 'data:image/png;base64,',
            accent: '#4e342e',
            instructions: 'Hold your hands in front of your chest or stomach, or near your ears. Shake both hands together in a forward and backward direction.'
        },
        {
            name: 'Grapes',
            signImg: 'data:image/png;base64,',
            accent: '#6a1b9a',
            instructions: 'Hold your non-dominant hand in front of you. Form a curved "5" handshape (claws) with your dominant hand. Place the fingertips of your dominant hand on the back of your non-dominant hand. "Bounce" or "step" your dominant fingertips down the length of your non-dominant hand toward your wrist in 2–3 small jumps.'
        },
        {
            name: 'Lemon',
            signImg: 'data:image/png;base64,',
            accent: '#f9a825',
            instructions: 'Form an "L" handshape with your dominant hand. Place the tip of your index finger against the side of your chin or cheek. Twist your wrist back and forth once or twice.'
        },
        {
            name: 'Pineapple',
            signImg: 'data:image/png;base64,',
            accent: '#e65100',
            instructions: 'Form a "P" handshape with your dominant hand. Place the middle fingertip on the side of your face near the cheek. Twist your wrist back and forth twice.'
        }
    ];

    const cardsHTML = fruits.map((f) => `
        <div class="asl-color-card">
            <div class="asl-sign-banner">
                <img class="asl-sign-img" src="${f.signImg}" alt="${f.name} ASL sign" loading="lazy" />
            </div>
            <div class="asl-color-card-body">
                <div class="asl-color-name-row">
                    <div class="asl-fruit-badge" style="background: ${f.accent};">${f.name.charAt(0)}</div>
                    <div class="asl-color-name-stack">
                        <div class="asl-color-name">${f.name}</div>
                        <div class="asl-color-subtitle">ASL Sign</div>
                    </div>
                </div>
                <div class="asl-color-divider"></div>
                <div class="asl-color-instructions">${f.instructions}</div>
                <div class="asl-color-hint">Tap to read more ↓</div>
            </div>
        </div>
    `).join('');

    return `
        <div class="asl-category-detail">
            <div class="asl-category-detail-header">
                <div class="asl-category-detail-title">Fruits 🍎</div>
                <div class="asl-category-detail-desc">Learn how to sign common fruits in ASL. Tap any card to see full instructions.</div>
            </div>
            <div class="asl-cards-grid" aria-label="ASL fruits">
                ${cardsHTML}
            </div>
        </div>
    `;
}

function attachASLFruitsPageHandlers() {
    const back = document.getElementById('backToASLLearningFromFruits');
    if (back) back.addEventListener('click', () => navigateTo('asl-learning'));
    document.querySelectorAll('.asl-color-card').forEach((card) => {
        card.addEventListener('click', () => card.classList.toggle('active'));
    });
}



