// ASL Everyday Things Page
// ===========================

function renderASLEverydayPage() {
    return `
        <div class="asl-page-container">
            <button class="back-btn" id="backToASLLearningFromEveryday">
                <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                    <polyline points="15 18 9 12 15 6"></polyline>
                </svg>
                <span>Back to ASL Learning</span>
            </button>
            ${renderASLEverydayCards()}
        </div>
    `;
}

function renderASLEverydayCards() {
    const phrases = [
        {
            word: 'Hello',
            signImg: 'data:image/png;base64,',
            emoji: '👋',
            accent: '#1565c0',
            instructions: 'Touch the tips of your fingers to your forehead or temple. Move your hand outward and away from your head in a short, slight arc — like a salute moving forward.'
        },
        {
            word: 'Goodbye',
            signImg: 'data:image/png;base64,',
            emoji: '🙋',
            accent: '#2e7d32',
            instructions: 'Open your palm facing outward. Fold your fingers down toward your palm twice, then open them again — similar to a "bye-bye" wave motion.'
        },
        {
            word: 'No',
            signImg: 'data:image/png;base64,',
            emoji: '❌',
            accent: '#c62828',
            instructions: 'Extend your index finger and middle finger together, and keep your thumb out. Quickly snap the tips of those two fingers down to meet your thumb. Shake your head slightly from side to side.'
        },
        {
            word: 'Yes',
            signImg: 'data:image/png;base64,',
            emoji: '✅',
            accent: '#2e7d32',
            instructions: 'Hold your fist at about shoulder or chin height and bend your wrist up and down — like a nodding motion. Physically nod your head along with the hand movement.'
        },
        {
            word: 'Help',
            signImg: 'data:image/png;base64,',
            emoji: '🤝',
            accent: '#e65100',
            instructions: 'Hold your non-dominant hand flat in front of you at chest height. Place your "thumbs up" dominant hand onto the palm of your flat hand. Move both hands together upward a few inches.'
        },
        {
            word: 'Stop',
            signImg: 'data:image/png;base64,',
            emoji: '✋',
            accent: '#b71c1c',
            instructions: 'Extend your non-dominant hand flat in front of you with the palm facing up. Bring the pinky-side edge of your dominant hand down sharply onto the palm — like a chopping motion.'
        },
        {
            word: 'Thank You',
            signImg: 'data:image/png;base64,',
            emoji: '🙏',
            accent: '#4527a0',
            instructions: 'Use your dominant hand with fingers together and palm facing inward toward your face. Touch your fingertips to your lips. Move your hand forward and slightly downward in a smooth arc.'
        },
        {
            word: 'Please',
            signImg: 'data:image/png;base64,',
            emoji: '😊',
            accent: '#00695c',
            instructions: 'Place your palm flat against the center of your chest. Move your hand in a circular motion, usually clockwise from your own perspective.'
        },
        {
            word: 'Sorry',
            signImg: 'data:image/png;base64,',
            emoji: '😔',
            accent: '#4e342e',
            instructions: 'Place the thumb-side of your fist against the center of your chest. Move your fist in a circular motion a few times.'
        },
        {
            word: 'Name',
            signImg: 'data:image/png;base64,',
            emoji: '🏷️',
            accent: '#1565c0',
            instructions: 'Hold your non-dominant hand still in front of you, fingers pointing sideways. Place the middle finger of your dominant "H" hand across the top of the non-dominant "H" hand. Tap your dominant fingers twice.'
        },
        {
            word: 'How',
            signImg: 'data:image/png;base64,',
            emoji: '🤔',
            accent: '#6a1b9a',
            instructions: 'Place your hands together in front of your chest with your fingertips/knuckles touching and your palms facing down. Roll your hands forward and upward so that your palms end up facing up.'
        },
        {
            word: 'What',
            signImg: 'data:image/png;base64,',
            emoji: '❓',
            accent: '#e65100',
            instructions: 'Hold your hands in front of you at waist or chest height. Move your hands back and forth horizontally (side to side) in a small, shaky, or questioning motion.'
        },
        {
            word: 'Where',
            signImg: 'data:image/png;base64,',
            emoji: '📍',
            accent: '#c62828',
            instructions: 'Hold your dominant hand in front of you at about chest or shoulder height with your index finger extended. Pivot your hand at the wrist, waving the finger side-to-side several times.'
        },
        {
            word: 'When',
            signImg: 'data:image/png;base64,',
            emoji: '🕐',
            accent: '#1b5e20',
            instructions: 'Place the tip of your dominant index finger near the tip of your non-dominant index finger. Move it in a complete circle (clockwise from your perspective) and then bring it back to land on the tip of the non-dominant finger.'
        },
        {
            word: 'Why',
            signImg: 'data:image/png;base64,',
            emoji: '🤷',
            accent: '#4527a0',
            instructions: 'Touch your fingers to your forehead (like a modified "think" sign). Pull your hand away from your head while transitioning your fingers into a "Y" handshape.'
        }
    ];

    const cardsHTML = phrases.map((p) => `
        <div class="asl-color-card">
            <div class="asl-sign-banner">
                <img class="asl-sign-img" src="${p.signImg}" alt="${p.word} ASL sign" loading="lazy" />
            </div>
            <div class="asl-color-card-body">
                <div class="asl-color-name-row">
                    <div class="asl-everyday-badge" style="background: ${p.accent};">${p.emoji}</div>
                    <div class="asl-color-name-stack">
                        <div class="asl-color-name">${p.word}</div>
                        <div class="asl-color-subtitle">ASL Sign</div>
                    </div>
                </div>
                <div class="asl-color-divider"></div>
                <div class="asl-color-instructions">${p.instructions}</div>
                <div class="asl-color-hint">Tap to read more ↓</div>
            </div>
        </div>
    `).join('');

    return `
        <div class="asl-category-detail">
            <div class="asl-category-detail-header">
                <div class="asl-category-detail-title">Grammar 📖</div>
                <div class="asl-category-detail-desc">Learn essential everyday ASL phrases. Tap any card to see full instructions.</div>
            </div>
            <div class="asl-cards-grid" aria-label="ASL everyday phrases">
                ${cardsHTML}
            </div>
        </div>
    `;
}

function attachASLEverydayPageHandlers() {
    const back = document.getElementById('backToASLLearningFromEveryday');
    if (back) back.addEventListener('click', () => navigateTo('asl-learning'));
    document.querySelectorAll('.asl-color-card').forEach((card) => {
        card.addEventListener('click', () => card.classList.toggle('active'));
    });
}

