function renderASLVegetablesCards() {
    const vegetables = [
        {
            name: 'Vegetable',
            signImg: 'data:image/png;base64,',
            accent: '#388e3c',
            instructions: 'Form a "V" handshape with your dominant hand. Place the tip of your index finger against your cheek, near the corner of your mouth. Twist the "V" back and forth twice.'
        },
        {
            name: 'Potato',
            signImg: 'data:image/png;base64,',
            accent: '#795548',
            instructions: 'Form a fist (an "S" handshape) and hold it in front of you with the back of your hand facing up. Form a bent "V" handshape (extend your index and middle fingers, then curve them like claws). Tap the tips of your bent fingers onto the back of your non-dominant fist twice.'
        },
        {
            name: 'Mushroom',
            signImg: 'data:image/png;base64,',
            accent: '#8d6e63',
            instructions: 'Extend your index finger (the "1" handshape) and hold it pointing straight up. Form a curved "5" handshape (palm facing down, fingers spread and slightly clawed). Place it over the top of the index finger like a mushroom cap and bounce it once or twice.'
        },
        {
            name: 'Tomato',
            signImg: 'data:image/png;base64,',
            accent: '#d32f2f',
            instructions: 'Form an "O" handshape with your non-dominant hand. Extend your dominant index finger. Touch the tip of your index finger to your chin or lips and stroke downward once. Bring that same index finger directly down to your non-dominant "O" hand in a slicing motion.'
        },
        {
            name: 'Cabbage',
            signImg: 'data:image/png;base64,',
            accent: '#558b2f',
            instructions: 'Form curved "5" handshapes (claws) with both hands. Place the heels of your palms against the sides of your head (near your temples or just above your ears). Tap your hands against your head twice. Your fingers should be spread and curved.'
        },
        {
            name: 'Lettuce',
            signImg: 'data:image/png;base64,',
            accent: '#7cb342',
            instructions: 'Form a curved "5" handshape (fingers spread and slightly clawed) with your dominant hand. Place the heel of your palm against your forehead or the upper side of your head. Tap your hand against your head twice.'
        },
        {
            name: 'Carrot',
            signImg: 'data:image/png;base64,',
            accent: '#ef6c00',
            instructions: 'Form a fist with your dominant hand, keeping your thumb on the outside. Bring your fist up to the side of your mouth. Move your hand slightly forward and away from your mouth while making a biting or chomping motion with your jaw.'
        },
        {
            name: 'Garlic',
            signImg: 'data:image/png;base64,',
            accent: '#f9a825',
            instructions: 'Form an "X" handshape with your dominant hand. Place the knuckle of your hooked index finger against the side of your nose. Twist your wrist back and forth twice.'
        },
        {
            name: 'Onion',
            signImg: 'data:image/png;base64,',
            accent: '#c0ca33',
            instructions: 'Form an "X" handshape with your dominant hand. Place the knuckle of your hooked index finger at the outer corner of your eye. Twist your wrist back and forth twice. It is very common to squint your eyes slightly while signing this.'
        },
        {
            name: 'Corn',
            signImg: 'data:image/png;base64,',
            accent: '#fbc02d',
            instructions: 'Form a "1" handshape (index finger extended) with your dominant hand. Hold your index finger horizontally just to the side of your mouth. Twist your finger forward (or downward) twice.'
        },
        {
            name: 'Celery',
            signImg: 'data:image/png;base64,',
            accent: '#689f38',
            instructions: 'Form a fist with your dominant hand. Hold your fist near the side of your mouth. Move your fist slightly forward (away from your face) in a short, jerky motion. As you move your hand, bite down firmly with your teeth and make a slight "scrunch" with your nose or cheeks.'
        }
    ];

    const cardsHTML = vegetables.map((v) => `
        <div class="asl-color-card">
            <div class="asl-sign-banner">
                <img class="asl-sign-img" src="${v.signImg}" alt="${v.name} ASL sign" loading="lazy" />
            </div>
            <div class="asl-color-card-body">
                <div class="asl-color-name-row">
                    <div class="asl-everyday-badge" style="background: ${v.accent};">🥦</div>
                    <div class="asl-color-name-stack">
                        <div class="asl-color-name">${v.name}</div>
                        <div class="asl-color-subtitle">ASL Sign</div>
                    </div>
                </div>
                <div class="asl-color-divider"></div>
                <div class="asl-color-instructions">${v.instructions}</div>
                <div class="asl-color-hint">Tap to read more ↓</div>
            </div>
        </div>
    `).join('');

    return `
        <div class="asl-category-detail">
            <div class="asl-category-detail-header">
                <div class="asl-category-detail-title">Vegetables 🥦</div>
                <div class="asl-category-detail-desc">Learn how to sign common vegetables in ASL. Tap any card to see full instructions.</div>
            </div>
            <div class="asl-cards-grid" aria-label="ASL vegetables">
                ${cardsHTML}
            </div>
        </div>
    `;
}

