// ===========================
// Quiz Functions
// ===========================

function startLevel(levelId) {
    appState.currentView = 'quiz';
    appState.quizState.currentLevelId = levelId;
    appState.quizState.currentQuestionIndex = 0;
    appState.quizState.selectedAnswer = null;
    appState.quizState.correctAnswers = 0;
    appState.quizState.answeredQuestions = [];
    appState.quizState.showFeedback = false;
    
    renderCurrentView();
}

function renderQuizPage() {
    const level = levelsData.find(l => l.id === appState.quizState.currentLevelId);
    if (!level) return '';

    const question = level.questions[appState.quizState.currentQuestionIndex];
    const progress = ((appState.quizState.currentQuestionIndex + 1) / level.questions.length) * 100;

    let optionsHTML = '';
    question.options.forEach((option, index) => {
        const isSelected = appState.quizState.selectedAnswer === index;
        const isCorrect = index === question.correctAnswer;
        const showCorrect = appState.quizState.showFeedback && isCorrect;
        const showIncorrect = appState.quizState.showFeedback && isSelected && !isCorrect;

        optionsHTML += `
            <button class="option-btn ${isSelected ? 'selected' : ''} ${showCorrect ? 'correct' : ''} ${showIncorrect ? 'incorrect' : ''}" 
                    data-index="${index}" 
                    ${appState.quizState.showFeedback ? 'disabled' : ''}>
                <span>${option}</span>
                ${showCorrect ? `
                    <div class="option-icon correct">
                        <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                            <polyline points="20 6 9 17 4 12"></polyline>
                        </svg>
                    </div>
                ` : ''}
                ${showIncorrect ? `
                    <div class="option-icon incorrect">
                        <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                            <line x1="18" y1="6" x2="6" y2="18"></line>
                            <line x1="6" y1="6" x2="18" y2="18"></line>
                        </svg>
                    </div>
                ` : ''}
            </button>
        `;
    });

    let indicatorsHTML = '';
    level.questions.forEach((_, index) => {
        let className = 'indicator pending';
        if (index < appState.quizState.currentQuestionIndex) {
            className = appState.quizState.answeredQuestions[index] ? 'indicator correct' : 'indicator incorrect';
        } else if (index === appState.quizState.currentQuestionIndex) {
            className = 'indicator current';
        }

        indicatorsHTML += `<div class="${className}">${index + 1}</div>`;
    });

    const isCorrect = appState.quizState.answeredQuestions[appState.quizState.answeredQuestions.length - 1];

    return `
        <div class="page-section">
            <div class="quiz-container">
                <button class="back-btn" id="backToHome">
                    <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        <line x1="19" y1="12" x2="5" y2="12"></line>
                        <polyline points="12 19 5 12 12 5"></polyline>
                    </svg>
                    <span>Back to Dashboard</span>
                </button>

                <div class="level-banner">
                    <h1>${level.title}</h1>
                    <p>${level.description}</p>
                </div>

                <div class="quiz-progress">
                    <div class="progress-info">
                        <span>Question ${appState.quizState.currentQuestionIndex + 1} of ${level.questions.length}</span>
                        <span>${Math.round(progress)}%</span>
                    </div>
                    <div class="progress-bar">
                        <div class="progress-fill" style="width: ${progress}%"></div>
                    </div>
                </div>

                <div class="question-card">
                    <h2 class="question-text">${question.question}</h2>
                    <div class="options-container">
                        ${optionsHTML}
                    </div>
                    <button class="btn-submit" id="submitBtn" 
                            ${appState.quizState.selectedAnswer === null || appState.quizState.showFeedback ? 'disabled' : ''}
                            style="${appState.quizState.showFeedback ? 'display: none;' : ''}">
                        Submit Answer
                    </button>
                    ${appState.quizState.showFeedback ? `
                        <div class="feedback-message show ${isCorrect ? 'correct' : 'incorrect'}">
                            <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                ${isCorrect 
                                    ? '<polyline points="20 6 9 17 4 12"></polyline>'
                                    : '<line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line>'
                                }
                            </svg>
                            ${isCorrect ? 'Correct! Great job! 🎉' : 'Not quite. Keep learning!'}
                        </div>
                    ` : ''}
                </div>

                <div class="question-indicators">
                    ${indicatorsHTML}
                </div>
            </div>
        </div>
    `;
}

function attachQuizHandlers() {
    // Back button
    document.getElementById('backToHome').addEventListener('click', goToDashboard);

    // Option buttons
    document.querySelectorAll('.option-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            if (appState.quizState.showFeedback) return;
            const index = parseInt(btn.getAttribute('data-index'));
            selectAnswer(index);
        });
    });

    // Submit button
    const submitBtn = document.getElementById('submitBtn');
    if (submitBtn) {
        submitBtn.addEventListener('click', submitAnswer);
    }
}

function selectAnswer(answerIndex) {
    appState.quizState.selectedAnswer = answerIndex;
    renderCurrentView();
}

function submitAnswer() {
    if (appState.quizState.selectedAnswer === null || appState.quizState.showFeedback) return;

    const level = levelsData.find(l => l.id === appState.quizState.currentLevelId);
    const question = level.questions[appState.quizState.currentQuestionIndex];
    const isCorrect = appState.quizState.selectedAnswer === question.correctAnswer;

    appState.quizState.showFeedback = true;
    appState.quizState.answeredQuestions.push(isCorrect);
    if (isCorrect) {
        appState.quizState.correctAnswers++;
    }

    renderCurrentView();

    setTimeout(() => {
        if (appState.quizState.currentQuestionIndex < level.questions.length - 1) {
            appState.quizState.currentQuestionIndex++;
            appState.quizState.selectedAnswer = null;
            appState.quizState.showFeedback = false;
            renderCurrentView();
        } else {
            completeLevel();
        }
    }, 2000);
}

// ===========================
// Badge Functions
// ===========================

function awardBadge(levelId) {
    const badge = badgesData.find(b => b.level === levelId);
    if (!badge) return;
    const isNew = !appState.earnedBadges.includes(Number(badge.id));
    if (isNew) {
        appState.earnedBadges.push(Number(badge.id));
        saveEarnedBadges();
        showBadgeToast(badge, levelId);
        // Immediately sync to profile so it's always up to date
        updateProfileModalData();
    }
}

function showBadgeToast(badge, levelId) {
    // Remove any existing toast
    const existing = document.getElementById('badgeToast');
    if (existing) existing.remove();

    const toast = document.createElement('div');
    toast.id = 'badgeToast';
    toast.className = 'badge-earned-toast';
    toast.innerHTML = `
        <img class="badge-toast-img" src="${badgeImages[levelId]}" alt="${badge.name}">
        <span>🎉 New Badge: ${badge.name}!</span>
    `;
    document.body.appendChild(toast);

    // Animate in
    setTimeout(() => toast.classList.add('show'), 50);

    // Animate out after 3.5s
    setTimeout(() => {
        toast.classList.remove('show');
        setTimeout(() => toast.remove(), 500);
    }, 3500);
}

function getBadgesEarned() {
    return badgesData.filter(b => appState.earnedBadges.includes(Number(b.id)));
}

function saveEarnedBadges() {
    localStorage.setItem('sign-connect-badges', JSON.stringify(appState.earnedBadges));
}

function completeLevel() {
    const level = levelsData.find(l => l.id === appState.quizState.currentLevelId);
    const score = Math.round((appState.quizState.correctAnswers / level.questions.length) * 100);
    const passed = score >= 60;

    if (passed && !appState.quizState.completedLevels.includes(appState.quizState.currentLevelId)) {
        appState.quizState.completedLevels.push(appState.quizState.currentLevelId);
        saveCompletedLevels();
        // Award badge for this level
        awardBadge(appState.quizState.currentLevelId);
    }

    appState.currentView = 'level-complete';
    renderCurrentView();

    if (passed) {
        createConfetti();
        createSparkles();
    }
}

function goToDashboard() {
    appState.currentView = 'dashboard';
    appState.currentPage = 'home';
    renderCurrentView();
}

// ===========================
// Level Complete Page
// ===========================

function renderLevelCompletePage() {
    const level = levelsData.find(l => l.id === appState.quizState.currentLevelId);
    if (!level) return '';

    const score = Math.round((appState.quizState.correctAnswers / level.questions.length) * 100);
    const passed = score >= 60;
    const stars = score >= 90 ? 3 : score >= 70 ? 2 : score >= 60 ? 1 : 0;
    const nextLevel = levelsData.find(l => l.id === appState.quizState.currentLevelId + 1);

    const getMessage = () => {
        if (!passed) return "💪 Don't give up! Try again to unlock the next level.";
        if (stars === 3) return "🌟 Perfect! You're an ASL superstar!";
        if (stars === 2) return "⭐ Great work! Keep it up!";
        return "✨ Nice job! You passed the level!";
    };

    let starsHTML = '';
    for (let i = 0; i < 3; i++) {
        starsHTML += `
            <svg class="star ${i < stars ? 'filled' : 'empty'}" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2">
                <polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2" />
            </svg>
        `;
    }

    return `
        <div class="page-section">
            <div class="confetti-container" id="confettiContainer"></div>
            <div class="sparkles-container" id="sparklesContainer"></div>

            <div class="complete-container">
                <div class="complete-card">
                    <div class="level-badge">
                        ${passed && badgeImages[appState.quizState.currentLevelId] ? 
                            `<img class="earned-badge-img" src="${badgeImages[appState.quizState.currentLevelId]}" alt="Badge">` :
                            `<span class="badge-icon">${passed ? '🎉' : '📚'}</span>`
                        }
                    </div>

                    <h1 class="complete-title">${passed ? 'Level Complete!' : 'Keep Practicing!'}</h1>
                    <p class="complete-subtitle">${level.title}</p>

                    <div class="score-display">
                        <div class="score-label">Your Score</div>
                        <div class="score-value">${score}%</div>
                    </div>

                    ${passed ? `
                        <div class="stars-container">
                            ${starsHTML}
                        </div>
                    ` : ''}

                    <div class="message-box ${passed ? 'pass' : 'fail'}">
                        <p>${getMessage()}</p>
                    </div>

                    ${passed && nextLevel ? `
                        <div class="unlock-card">
                            <div class="unlock-sparkles">
                                <span>✨</span>
                                <h3>Level Unlocked!</h3>
                                <span>✨</span>
                            </div>
                            <p class="unlock-title">${nextLevel.title}</p>
                            <p class="unlock-description">${nextLevel.description}</p>
                            <div class="unlock-trophy">🏆</div>
                        </div>
                    ` : ''}

                    <div class="action-buttons">
                        <button class="btn-outline" id="backToDashboardBtn">
                            <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                <path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"></path>
                            </svg>
                            Back to Dashboard
                        </button>
                        <button class="btn-gradient" id="nextActionBtn">
                            <span>${passed && nextLevel ? 'Next Level' : passed ? 'View Progress' : 'Try Again'}</span>
                            <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                <line x1="5" y1="12" x2="19" y2="12"></line>
                                <polyline points="12 5 19 12 12 19"></polyline>
                            </svg>
                        </button>
                    </div>
                </div>
            </div>
        </div>
    `;
}

function attachLevelCompleteHandlers() {
    document.getElementById('backToDashboardBtn').addEventListener('click', goToDashboard);
    
    const nextActionBtn = document.getElementById('nextActionBtn');
    const level = levelsData.find(l => l.id === appState.quizState.currentLevelId);
    const score = Math.round((appState.quizState.correctAnswers / level.questions.length) * 100);
    const passed = score >= 60;
    const nextLevel = levelsData.find(l => l.id === appState.quizState.currentLevelId + 1);

    nextActionBtn.addEventListener('click', () => {
        if (passed && nextLevel) {
            startLevel(nextLevel.id);
        } else if (passed) {
            goToDashboard();
        } else {
            startLevel(appState.quizState.currentLevelId);
        }
    });
}

