const VI_BACKEND_URL = 'http://127.0.0.1:5000';

// Runtime state
const viState = {
    active: false,
    mode: null,
    history: [],
    animFrameId: null,
    videoStream: null,
    hands: null,
    sentence: [],
    lastSign: null,
    addCooldown: false,
    mpReady: false,
    predictInFlight: false,
};

function viGetModeDisplayName(mode) {
    if (mode === 'alphabet') return 'Alphabet';
    if (mode === 'letters') return 'Letter';
    if (mode === 'phrases') return 'Phrase';
    return 'Sign';
}

function viUpdateDetectSectionForMode() {
    const currentLabelEl = document.getElementById('viCurrentLabel');
    if (!currentLabelEl) return;
    currentLabelEl.textContent = `Detected ${viGetModeDisplayName(viState.mode)}`;
}

