// ── Attach handlers + boot libraries ────────────────────────────────────
function attachVisualInterpreterHandlers() {
    // Reset state cleanly
    viStopDetection();
    viState.mode = null;
    viState.history = [];
    viState.sentence = [];
    viState.mpReady = false;
    viUpdateDetectSectionForMode();

    // Load CDN libraries then init
    viLoadLibraries();

    document.querySelectorAll('.vi-mode-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            document.querySelectorAll('.vi-mode-btn').forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            viState.mode = btn.dataset.mode;
            document.getElementById('viStartBtn').disabled = false;
            viUpdateDetectSectionForMode();
        });
    });

    document.getElementById('viStartBtn')?.addEventListener('click', viStartDetection);
    document.getElementById('viStopBtn')?.addEventListener('click', viStopDetection);
    document.getElementById('viClearBtn')?.addEventListener('click', () => {
        viState.history = [];
        viUpdateHistoryUI();
    });
    document.getElementById('viAddWordBtn')?.addEventListener('click', viAddToSentence);
    document.getElementById('viCopyBtn')?.addEventListener('click', viCopySentence);
    document.getElementById('viSpeakBtn')?.addEventListener('click', viSpeakSentence);
    document.getElementById('viEraseWordBtn')?.addEventListener('click', viEraseWord);
}

// ── Load MediaPipe from CDN ───────────────────────────────────────────────
function viLoadLibraries() {
    const dot  = document.getElementById('viStatusDot');
    const text = document.getElementById('viStatusText');

    // Check if already loaded
    if (window.Hands) {
        viOnLibrariesReady();
        return;
    }

    text.textContent = 'Loading MediaPipe Hands…';
    const mpScript = document.createElement('script');
    mpScript.src = 'https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1646424915/hands.js';
    mpScript.onload = () => {
        const mpCamScript = document.createElement('script');
        mpCamScript.src = 'https://cdn.jsdelivr.net/npm/@mediapipe/camera_utils/camera_utils.js';
        mpCamScript.onload = () => viOnLibrariesReady();
        mpCamScript.onerror = () => viOnLibError('MediaPipe camera utils failed to load');
        document.head.appendChild(mpCamScript);
    };
    mpScript.onerror = () => viOnLibError('MediaPipe Hands failed to load');
    document.head.appendChild(mpScript);
}

function viOnLibrariesReady() {
    const dot  = document.getElementById('viStatusDot');
    const text = document.getElementById('viStatusText');
    if (!dot || !text) return;

    dot.className = 'vi-status-dot online';
    text.textContent = '✅ Ready — select a mode and press Start';

    document.getElementById('viModeBar').style.display = 'block';
    document.getElementById('viMain').style.display = 'grid';
    document.getElementById('viTipsRow').style.display = 'grid';
    viState.mpReady = true;
}

function viOnLibError(msg) {
    const dot  = document.getElementById('viStatusDot');
    const text = document.getElementById('viStatusText');
    if (!dot || !text) return;
    dot.className = 'vi-status-dot offline';
    text.textContent = '❌ ' + msg;
}

function viSetStatusOnline(msg) {
    const dot  = document.getElementById('viStatusDot');
    const text = document.getElementById('viStatusText');
    if (!dot || !text) return;
    dot.className = 'vi-status-dot online';
    text.textContent = msg;
}

async function viCheckBackend(mode) {
    const loadEl = document.getElementById('viModelLoading');
    const loadTxt = document.getElementById('viModelLoadText');
    if (loadEl) loadEl.style.display = 'flex';
    if (loadTxt) loadTxt.textContent = `Connecting ${viGetModeDisplayName(mode)} model backend…`;
    try {
        const response = await fetch(`${VI_BACKEND_URL}/health`, { method: 'GET' });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const payload = await response.json();
        if (!payload.ok) throw new Error('Backend health check failed');
        viSetStatusOnline('✅ Backend connected — select mode and press Start');
        return true;
    } catch (e) {
        viOnLibError('Python backend not running. Start detect_api.py on port 5000.');
        return false;
    } finally {
        if (loadEl) loadEl.style.display = 'none';
    }
}

// ── Start detection ───────────────────────────────────────────────────────
async function viStartDetection() {
    if (!viState.mode || !viState.mpReady) return;

    const backendReady = await viCheckBackend(viState.mode);
    if (!backendReady) return;

    // Get camera
    try {
        viState.videoStream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
    } catch (e) {
        viOnLibError('Camera access denied. Please allow camera permissions.');
        return;
    }

    const video  = document.getElementById('viVideo');
    const canvas = document.getElementById('viCanvas');
    video.srcObject = viState.videoStream;
    video.style.display = 'block';
    canvas.style.display = 'block';
    document.getElementById('viCameraPlaceholder').style.display = 'none';
    document.getElementById('viStartBtn').style.display = 'none';
    document.getElementById('viStopBtn').style.display = 'flex';

    viState.active = true;

    // Setup MediaPipe Hands
    const phrasesMode = viState.mode === 'phrases';
    viState.hands = new Hands({
        locateFile: (file) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1646424915/${file}`
    });
    viState.hands.setOptions({
        maxNumHands: phrasesMode ? 2 : 1,
        modelComplexity: 1,
        minDetectionConfidence: 0.7,
        minTrackingConfidence: 0.5,
    });
    viState.hands.onResults(viOnHandResults);

    // Process frames
    const processFrame = async () => {
        if (!viState.active) return;
        if (video.readyState >= 2) {
            canvas.width  = video.videoWidth;
            canvas.height = video.videoHeight;
            await viState.hands.send({ image: video });
        }
        viState.animFrameId = requestAnimationFrame(processFrame);
    };
    video.onloadedmetadata = () => { processFrame(); };
}

// ── Stop detection ────────────────────────────────────────────────────────
function viStopDetection() {
    viState.active = false;
    viState.predictInFlight = false;

    if (viState.animFrameId) { cancelAnimationFrame(viState.animFrameId); viState.animFrameId = null; }
    if (viState.hands) { viState.hands.close(); viState.hands = null; }
    if (viState.videoStream) {
        viState.videoStream.getTracks().forEach(t => t.stop());
        viState.videoStream = null;
    }

    const video  = document.getElementById('viVideo');
    const canvas = document.getElementById('viCanvas');
    if (video)  { video.srcObject = null; video.style.display = 'none'; }
    if (canvas) canvas.style.display = 'none';

    const placeholder = document.getElementById('viCameraPlaceholder');
    const startBtn    = document.getElementById('viStartBtn');
    const stopBtn     = document.getElementById('viStopBtn');
    if (placeholder) placeholder.style.display = 'flex';
    if (startBtn)    startBtn.style.display = 'flex';
    if (stopBtn)     stopBtn.style.display  = 'none';

    const signEl = document.getElementById('viCurrentSign');
    const barEl  = document.getElementById('viConfidenceBar');
    const txtEl  = document.getElementById('viConfidenceText');
    if (signEl) signEl.textContent = '—';
    if (barEl)  barEl.style.width  = '0%';
    if (txtEl)  txtEl.textContent  = 'Confidence: 0%';
    viUpdateDetectSectionForMode();
}

// ── MediaPipe results → Python backend (.pkl) inference ──────────────────
async function viOnHandResults(results) {
    // Draw skeleton on canvas
    const canvas = document.getElementById('viCanvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
        for (const lms of results.multiHandLandmarks) {
            drawConnectors(ctx, lms, HAND_CONNECTIONS, { color: '#5DB6BE', lineWidth: 2 });
            drawLandmarks(ctx, lms, { color: '#4A9BA8', lineWidth: 1, radius: 4 });
        }

        // Build feature vector
        let features = [];
        const phrasesMode = viState.mode === 'phrases';

        if (phrasesMode) {
            for (const hand of results.multiHandLandmarks) {
                for (const lm of hand) features.push(lm.x, lm.y, lm.z);
            }
            while (features.length < 126) features.push(0);
            features = features.slice(0, 126);
        } else {
            const hand = results.multiHandLandmarks[0];
            for (const lm of hand) features.push(lm.x, lm.y, lm.z);
            features = features.slice(0, 63);
        }

        if (viState.predictInFlight) return;
        viState.predictInFlight = true;
        try {
            const res = await fetch(`${VI_BACKEND_URL}/predict`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ mode: viState.mode, features }),
            });
            if (!res.ok) throw new Error(`HTTP ${res.status}`);
            const data = await res.json();
            const label = data?.label ? String(data.label) : '—';
            const confidence = Number.isFinite(data?.confidence) ? Math.max(0, Math.min(100, Math.round(data.confidence))) : 100;

            viUpdatePredictionUI(label, confidence);

            if (label !== '—' && label !== viState.lastSign && confidence >= 80 && !viState.addCooldown) {
                viState.lastSign = label;
                viState.addCooldown = true;
                viAddToHistory(label, confidence, viState.mode);
                setTimeout(() => { viState.addCooldown = false; }, 1500);
            }
        } catch (e) {
            console.error('[Backend inference error]', e);
            viOnLibError('Backend prediction failed. Make sure detect_api.py is running.');
        } finally {
            viState.predictInFlight = false;
        }
    } else {
        // No hand detected
        viUpdatePredictionUI('—', 0);
    }
}

// ── UI helpers ────────────────────────────────────────────────────────────
function viUpdatePredictionUI(label, confidence) {
    const signEl = document.getElementById('viCurrentSign');
    const barEl  = document.getElementById('viConfidenceBar');
    const txtEl  = document.getElementById('viConfidenceText');
    if (!signEl) return;

    signEl.textContent = label;
    barEl.style.width  = confidence + '%';
    txtEl.textContent  = `Confidence: ${confidence}%`;

    if (confidence >= 80)      barEl.style.background = '#22c55e';
    else if (confidence >= 50) barEl.style.background = '#f59e0b';
    else                       barEl.style.background = '#ef4444';
}

function viAddToHistory(label, confidence, mode) {
    viState.history.unshift({ label, confidence, mode, time: new Date().toLocaleTimeString() });
    if (viState.history.length > 30) viState.history.pop();
    viUpdateHistoryUI();
}

function viUpdateHistoryUI() {
    const list = document.getElementById('viHistoryList');
    if (!list) return;
    if (viState.history.length === 0) {
        list.innerHTML = '<p class="vi-history-empty">No detections yet</p>';
        return;
    }
    list.innerHTML = viState.history.map(h => `
        <div class="vi-history-item">
            <span class="vi-history-sign">${h.label}</span>
            <span class="vi-history-meta">${h.confidence}% · ${viGetModeDisplayName(h.mode)} · ${h.time}</span>
        </div>
    `).join('');
}

// Sentence builder
function viAddToSentence() {
    const sign = document.getElementById('viCurrentSign')?.textContent;
    if (!sign || sign === '—') return;
    viState.sentence.push(sign);
    viRenderSentence();
}

function viRenderSentence() {
    const box = document.getElementById('viSentenceBox');
    if (!box) return;
    if (viState.sentence.length === 0) {
        box.innerHTML = '<span class="vi-sentence-placeholder">Signs you add will appear here…</span>';
    } else {
        box.innerHTML = viState.sentence.map(w =>
            `<span class="vi-sentence-word">${w}</span>`
        ).join(' ');
    }
}

function viCopySentence() {
    const text = viState.sentence.join(' ');
    if (!text) return;
    navigator.clipboard.writeText(text).then(() => {
        const btn = document.getElementById('viCopyBtn');
        if (btn) { btn.textContent = '✅ Copied!'; setTimeout(() => { btn.textContent = '📋 Copy'; }, 1500); }
    });
}

function viSpeakSentence() {
    const text = viState.sentence.join(' ');
    if (!text || !window.speechSynthesis) return;
    window.speechSynthesis.speak(new SpeechSynthesisUtterance(text));
}

function viEraseWord() {
    viState.sentence.pop();
    viRenderSentence();
}


