function attachDonationHandlers() {
    // Trigger card entrance animations
    const cards = document.querySelectorAll('.don-org-card');
    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('don-card-visible');
                observer.unobserve(entry.target);
            }
        });
    }, { threshold: 0.1 });
    cards.forEach(card => observer.observe(card));

    // Shine effect on mouse move
    cards.forEach(card => {
        card.addEventListener('mousemove', (e) => {
            const rect = card.getBoundingClientRect();
            const x = ((e.clientX - rect.left) / rect.width) * 100;
            const y = ((e.clientY - rect.top) / rect.height) * 100;
            card.querySelector('.don-org-shine').style.background =
                `radial-gradient(circle at ${x}% ${y}%, rgba(255,255,255,0.08) 0%, transparent 60%)`;
        });
        card.addEventListener('mouseleave', () => {
            card.querySelector('.don-org-shine').style.background = 'none';
        });
    });
}


