// ── Task view ─────────────────────────────────────────────────────────────
function renderDTTaskView() {
    const task = dailyTasksData[dtState.currentTask];
    const wIdx = dtState.currentWordIdx;
    const word = task.words[wIdx];
    const letters = task.wordLetters[wIdx];
    const typed = dtState.typedLetters[wIdx] || [];
    const isLastWord = wIdx === task.words.length - 1;
    const wordDone = typed.length === letters.length;
    const allDone = dtState.taskComplete;

    // ASL fingerspelling image map (lifeprint.com open-access images)
    const aslImgBase = 'https://www.lifeprint.com/asl101/fingerspelling/abc-gifs/';
    const aslImgMap = {
        A:'a',B:'b',C:'c',D:'d',E:'e',F:'f',G:'g',H:'h',I:'i',J:'j',
        K:'k',L:'l',M:'m',N:'n',O:'o',P:'p',Q:'q',R:'r',S:'s',T:'t',
        U:'u',V:'v',W:'w',X:'x',Y:'y',Z:'z'
    };

    // Build sign strip — images shown, letter revealed only after typing
    const signsHTML = letters.map((l, i) => {
        const t = typed[i];
        const isActive = i === typed.length && !wordDone;
        const isAnswered = !!t;
        const imgKey = aslImgMap[l.sign.toUpperCase()] || l.sign.toLowerCase();
        const imgSrc = aslImgBase + imgKey + '.gif';

        let cls = 'dt-sign-card';
        let overlay = '';
        let revealedLetter = '';

        if (t) {
            if (t.status === 'correct') {
                cls += ' dt-sign-correct';
                overlay = '<div class="dt-sign-overlay correct">✓</div>';
                revealedLetter = `<div class="dt-sign-revealed correct">${l.sign}</div>`;
            } else {
                cls += ' dt-sign-wrong';
                overlay = '<div class="dt-sign-overlay wrong">✗</div>';
                revealedLetter = `<div class="dt-sign-revealed wrong">${l.sign}</div>`;
            }
        } else if (isActive) {
            cls += ' dt-sign-active';
        }

        return `
        <div class="${cls}" style="--si:${i}; --tc:${task.color}" title="${isActive ? 'Type this letter!' : (isAnswered ? 'Sign for ' + l.sign : 'Upcoming sign')}">
            ${overlay}
            ${revealedLetter}
            <div class="dt-sign-img-wrap ${isActive ? 'dt-img-active' : ''} ${!isAnswered && !isActive ? 'dt-img-upcoming' : ''}">
                <img class="dt-sign-img" src="${imgSrc}" alt="ASL sign for ${l.sign}"
                     onerror="this.style.display='none';this.nextElementSibling.style.display='flex'"
                     loading="lazy" />
                <div class="dt-sign-img-fallback" style="display:none;background:${isActive ? task.gradient : '#64748b'}">${l.sign}</div>
            </div>
            <div class="dt-sign-hint">${l.desc}</div>
        </div>`;
    }).join('');

    // Build word progress dots
    const wordDotsHTML = task.words.map((w, i) => {
        let cls = 'dt-word-dot';
        if (i < wIdx || (i === wIdx && wordDone)) {
            cls += dtState.wordResults[i] === 'correct' ? ' dt-dot-correct' : ' dt-dot-done';
        } else if (i === wIdx) cls += ' dt-dot-active';
        return `<div class="${cls}"><span>${w}</span></div>`;
    }).join('');

    // Build typing input area - show blank slots
    const slotsHTML = letters.map((l, i) => {
        const t = typed[i];
        let val = t ? t.letter : '';
        let cls = 'dt-slot';
        if (t) cls += t.status === 'correct' ? ' dt-slot-correct' : ' dt-slot-wrong';
        else if (i === typed.length) cls += ' dt-slot-active';
        return `<div class="${cls}">${val}</div>`;
    }).join('');

    // Word result feedback
    let feedbackHTML = '';
    if (wordDone) {
        const wr = dtState.wordResults[wIdx];
        const allCorrect = typed.every(t => t.status === 'correct');
        feedbackHTML = `
        <div class="dt-word-feedback ${allCorrect ? 'dt-fb-correct' : 'dt-fb-wrong'}">
            <span class="dt-fb-icon">${allCorrect ? '🎉' : '💡'}</span>
            <div>
                <strong>${allCorrect ? 'Perfect!' : 'The word was: ' + word}</strong>
                <p>${allCorrect ? 'You got every letter right!' : 'Study the signs above and try the next word.'}</p>
            </div>
        </div>`;
    }

    // Final result if all done
    let finalHTML = '';
    if (allDone) {
        const correctCount = dtState.wordResults.filter(r => r === 'correct').length;
        const total = task.words.length;
        const perfect = correctCount === total;
        finalHTML = `
        <div class="dt-final-result ${perfect ? 'dt-final-perfect' : 'dt-final-ok'}">
            <div class="dt-final-icon">${perfect ? '🏆' : '👏'}</div>
            <h3>${perfect ? 'Excellent! All words correct!' : `${correctCount}/${total} words correct — keep practising!`}</h3>
            <p>You fingerspelled: <strong style="color:${task.color}">${task.phrase}</strong></p>
            <div class="dt-final-actions">
                ${dtState.currentTask < dailyTasksData.length - 1 
                    ? `<button class="dt-next-task-btn" id="dtNextTaskBtn" style="background:${task.gradient}">➡ Next Task</button>`
                    : `<button class="dt-next-task-btn" id="dtNextTaskBtn" style="background:${task.gradient}">🏆 All Tasks Done!</button>`
                }
                <button class="dt-retry-task-btn" id="dtRetryTaskBtn">🔁 Try Again</button>
            </div>
        </div>`;
    }

    return `
    <div class="page-section dt-page">
        <button class="dt-back-btn" id="dtBackBtn">
            <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                <line x1="19" y1="12" x2="5" y2="12"></line><polyline points="12 19 5 12 12 5"></polyline>
            </svg>
            Back to Tasks
        </button>

        <!-- Task header -->
        <div class="dt-task-header" style="--tc:${task.color}">
            <div class="dt-task-header-bg" style="background:${task.gradient}"></div>
            <div class="dt-task-header-content">
                <span class="dt-task-header-badge">Task ${task.id} of ${dailyTasksData.length}</span>
                <div class="dt-task-header-emoji">${task.emoji}</div>
                <h1 class="dt-task-header-phrase">${task.phrase}</h1>
                <p class="dt-task-header-hint">${task.hint}</p>
            </div>
        </div>

        <!-- Word progress bar -->
        <div class="dt-word-progress">
            <p class="dt-word-progress-label">Progress</p>
            <div class="dt-word-dots">${wordDotsHTML}</div>
        </div>

        <!-- Current word -->
        ${!allDone ? `
        <div class="dt-current-word-section">
            <div class="dt-current-word-header">
                <h2 class="dt-cw-title">Word ${wIdx + 1} of ${task.words.length}</h2>
                <div class="dt-cw-badge" style="background:${task.gradient}">Type what you see 👇</div>
            </div>

            <!-- Quiz instruction -->
            <div class="dt-quiz-instruction">
                <div class="dt-qi-dot"></div>
                <span>Look at each hand sign image, then <strong>type the letter it represents</strong> using your keyboard — left to right.</span>
            </div>

            <!-- Sign cards -->
            <div class="dt-signs-grid" id="dtSignsGrid">${signsHTML}</div>

            <!-- Typing slots -->
            <div class="dt-typing-area">
                <p class="dt-typing-label">Your answer — type each letter:</p>
                <div class="dt-slots-row" id="dtSlotsRow">${slotsHTML}</div>

                <!-- Keyboard hint -->
                <div class="dt-keyboard-hint">⌨️ Use your keyboard to type · <kbd>Backspace</kbd> to delete</div>

                <!-- Hidden input to capture keystrokes -->
                <input type="text" id="dtHiddenInput" class="dt-hidden-input"
                       autocomplete="off" autocorrect="off" autocapitalize="off"
                       spellcheck="false" maxlength="1" />
            </div>

            <!-- Word feedback -->
            ${feedbackHTML}

            <!-- Next word / submit -->
            ${wordDone && !allDone ? `
            <div class="dt-word-actions">
                ${!isLastWord 
                    ? `<button class="dt-next-word-btn" id="dtNextWordBtn" style="background:${task.gradient}">Next Word ➡</button>`
                    : `<button class="dt-next-word-btn" id="dtNextWordBtn" style="background:${task.gradient}">See Results 🏁</button>`
                }
            </div>` : ''}
        </div>` : ''}

        <!-- Final result -->
        ${finalHTML}

        <!-- Tip -->
        ${!allDone ? `
        <div class="dt-tip-box" style="border-color:${task.color}30; background:${task.color}08">
            <span class="dt-tip-icon">💡</span>
            <p>Study the hand shape, letter name and description for each sign. Type the letters in order!</p>
        </div>` : ''}
    </div>`;
}

// ── Attach handlers ───────────────────────────────────────────────────────
function attachDailyTasksHandlers() {
    // Animate cards in
    setTimeout(() => {
        document.querySelectorAll('.dt-task-card').forEach((c, i) => {
            setTimeout(() => c.classList.add('dt-card-in'), i * 80);
        });
    }, 50);

    // Start task
    document.querySelectorAll('.dt-start-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            dtStartTask(parseInt(btn.dataset.task));
        });
    });
    document.querySelectorAll('.dt-task-card').forEach(card => {
        card.addEventListener('click', () => dtStartTask(parseInt(card.dataset.task)));
    });

    // Back
    document.getElementById('dtBackBtn')?.addEventListener('click', () => {
        dtState.view = 'list';
        dtState.currentTask = null;
        renderCurrentView();
    });

    // Next word
    document.getElementById('dtNextWordBtn')?.addEventListener('click', dtNextWord);

    // Next task
    document.getElementById('dtNextTaskBtn')?.addEventListener('click', () => {
        if (dtState.currentTask < dailyTasksData.length - 1) {
            dtStartTask(dtState.currentTask + 1);
        } else {
            dtState.view = 'list';
            dtState.currentTask = null;
            renderCurrentView();
        }
    });

    // Retry
    document.getElementById('dtRetryTaskBtn')?.addEventListener('click', () => {
        dtStartTask(dtState.currentTask);
    });

    // Typing — focus hidden input on click of sign area
    const hiddenInput = document.getElementById('dtHiddenInput');
    if (hiddenInput) {
        // Auto-focus
        setTimeout(() => hiddenInput.focus(), 100);

        document.getElementById('dtSignsGrid')?.addEventListener('click', () => hiddenInput.focus());
        document.getElementById('dtSlotsRow')?.addEventListener('click', () => hiddenInput.focus());

        hiddenInput.addEventListener('keydown', (e) => {
            e.preventDefault();
            const task = dailyTasksData[dtState.currentTask];
            const wIdx = dtState.currentWordIdx;
            const letters = task.wordLetters[wIdx];
            const typed = dtState.typedLetters[wIdx] || [];

            if (e.key === 'Backspace') {
                if (typed.length > 0 && typed.length < letters.length) {
                    dtState.typedLetters[wIdx].pop();
                    renderCurrentView();
                    setTimeout(() => document.getElementById('dtHiddenInput')?.focus(), 50);
                }
                return;
            }

            const key = e.key.toUpperCase();
            if (!/^[A-Z]$/.test(key)) return;
            if (typed.length >= letters.length) return;

            const expected = letters[typed.length].sign.toUpperCase();
            const status = key === expected ? 'correct' : 'wrong';

            if (!dtState.typedLetters[wIdx]) dtState.typedLetters[wIdx] = [];
            dtState.typedLetters[wIdx].push({ letter: key, status });

            // Check if word complete
            if (dtState.typedLetters[wIdx].length === letters.length) {
                const allCorrect = dtState.typedLetters[wIdx].every(t => t.status === 'correct');
                dtState.wordResults[wIdx] = allCorrect ? 'correct' : 'wrong';

                // Check if all words done
                if (wIdx === task.words.length - 1) {
                    dtState.taskComplete = true;
                    // Mark as completed & update streak
                    if (!dtState.completed.includes(task.id)) {
                        dtState.completed.push(task.id);
                        localStorage.setItem('dt_completed', JSON.stringify(dtState.completed));
                        const today = new Date().toDateString();
                        if (dtState.lastDate !== today) {
                            dtState.streak++;
                            dtState.lastDate = today;
                            localStorage.setItem('dt_streak', String(dtState.streak));
                            localStorage.setItem('dt_lastDate', today);
                        }
                    }
                }
            }

            renderCurrentView();
            // Re-focus after re-render
            if (!dtState.taskComplete) {
                setTimeout(() => document.getElementById('dtHiddenInput')?.focus(), 50);
            }
        });
    }
}

function dtStartTask(idx) {
    dtState.currentTask = idx;
    dtState.view = 'task';
    dtState.currentWordIdx = 0;
    dtState.typedLetters = [];
    dtState.wordResults = [];
    dtState.taskComplete = false;
    renderCurrentView();
}

function dtNextWord() {
    dtState.currentWordIdx++;
    renderCurrentView();
    setTimeout(() => document.getElementById('dtHiddenInput')?.focus(), 100);
}
