// ===========================
// Render Alphabet Cards
// ===========================

function renderAlphabetCards() {
  const container = document.getElementById("mainContainer");

  let html = `
    <div class="page-section">
      <button onclick="renderASLLearning()" class="back-btn">← Back to ASL Learning</button>

      <div class="page-header">
        <div class="page-header-content">
          <h1 class="page-header-title">🔤 Letters & Alphabets</h1>
          <p class="page-header-description">
            Learn ASL alphabets. Tap any card to see full instructions.
          </p>
        </div>
      </div>

      <div class="cards-grid">
  `;

  aslAlphabetData.forEach(item => {
    html += `
      <div class="asl-card" onclick="toggleCard(this)">
        <div class="asl-card-top">
          <div class="asl-letter">${item.letter}</div>
          <div>
            <h3>${item.letter}</h3>
            <p>ASL SIGN</p>
          </div>
        </div>

        <div class="asl-desc short">
          ${item.desc.substring(0, 60)}...
        </div>

        <div class="asl-desc full hidden">
          ${item.desc}
        </div>

        <span class="read-more">Tap to read more ↓</span>
      </div>
    `;
  });

  html += `</div></div>`;
  container.innerHTML = html;
}


// ===========================
// Toggle Expand
// ===========================

function toggleCard(card) {
  const shortText = card.querySelector(".short");
  const fullText = card.querySelector(".full");

  shortText.classList.toggle("hidden");
  fullText.classList.toggle("hidden");
}